package org.researchdock.mobile;
import org.json.*;
import org.junit.Test;
import java.time.*;
import static org.junit.Assert.*;
public class ResearchHomeTest {
 private JSONObject health(String state)throws Exception{return new JSONObject().put("poll_enabled",true).put("poll_minutes",5).put("sources",new JSONArray().put(new JSONObject().put("status",state).put("last_success_at","2026-10-25T09:59:00+08:00")));}
 @Test public void todayCollectedUsesFirstImportInShanghaiNotPublicationOrSequence()throws Exception{JSONObject d=new JSONObject().put("first_imported_at","2026-10-24T16:30:00Z").put("published_at","2026-01-01T10:00:00+08:00").put("sequence",999);LocalDate today=LocalDate.of(2026,10,25);assertTrue(ResearchHome.importedToday(d,today));assertTrue(LibraryViews.matches(d,"","",0,"今日收录",false,false,0,today));d.put("first_imported_at","2026-10-24T15:30:00Z");assertFalse(ResearchHome.importedToday(d,today));d.remove("first_imported_at");assertFalse(ResearchHome.importedToday(d,today));}
 @Test public void failuresPartialAndMissingReportsNeverLookHealthy()throws Exception{long now=ResearchHome.epoch("2026-10-25T10:00:00+08:00");String received="2026-10-25T09:59:50+08:00";assertFalse(ResearchHome.healthy(health("failed"),received,now));assertTrue(ResearchHome.healthLabel(health("failed"),received,now).contains("采集异常"));assertFalse(ResearchHome.healthy(health("partial"),received,now));assertFalse(ResearchHome.healthy(null,received,now));assertFalse(ResearchHome.healthy(health("unknown"),received,now));}
 @Test public void staleMacAndStaleCollectionAreVisibleEvenWithHealthyCloud()throws Exception{long now=ResearchHome.epoch("2026-10-25T10:00:00+08:00");assertTrue(ResearchHome.healthy(health("succeeded"),"2026-10-25T09:59:50+08:00",now));assertTrue(ResearchHome.healthLabel(health("succeeded"),"2026-10-25T09:50:00+08:00",now).contains("已过期"));JSONObject old=health("succeeded");old.getJSONArray("sources").getJSONObject(0).put("last_success_at","2026-10-25T09:00:00+08:00");assertTrue(ResearchHome.healthLabel(old,"2026-10-25T09:59:50+08:00",now).contains("延迟"));}
 @Test public void disabledPollingIsNotAdvertisedAsAutomaticCollection()throws Exception{JSONObject h=health("succeeded");h.put("poll_enabled",false);assertTrue(ResearchHome.healthLabel(h,"2026-10-25T09:59:50+08:00",ResearchHome.epoch("2026-10-25T10:00:00+08:00")).contains("已关闭"));}
 @Test public void analysisRequiresMatchingPositiveRevision()throws Exception{JSONObject d=new JSONObject().put("revision",2).put("analysis_revision",1);assertFalse(ResearchHome.analysisCurrent(d));d.put("analysis_revision",2);assertTrue(ResearchHome.analysisCurrent(d));assertFalse(ResearchHome.analysisCurrent(new JSONObject()));}
 @Test public void originalTitlesStayAvailableAndAttachmentSummaryUsesRealCounts()throws Exception{JSONObject d=new JSONObject().put("title","原始标题").put("display_title","合成.pdf").put("attachments",new JSONArray().put(new JSONObject().put("type","pdf")).put(new JSONObject().put("type","audio")));assertEquals("合成.pdf",ResearchHome.displayTitle(d));assertEquals("原始标题",d.getString("title"));assertTrue(ResearchHome.attachmentSummary(d).contains("PDF 1"));assertTrue(ResearchHome.attachmentSummary(d).contains("音频 1"));}
}
